testsCode:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { copiarProfundo, atualizarSemMutar } from './solution.mjs';

test('copiarProfundo devolve objeto novo com as mesmas propriedades', () => {
  const original = { nome: 'Ana', idade: 15 };
  const copia = copiarProfundo(original);
  assert.deepEqual(copia, { nome: 'Ana', idade: 15 });
  assert.notEqual(copia, original);
});

test('copiarProfundo copia os objetos aninhados de verdade', () => {
  const original = { nome: 'Ana', endereco: { cidade: 'São Paulo' } };
  const copia = copiarProfundo(original);
  copia.endereco.cidade = 'Campinas';
  assert.equal(original.endereco.cidade, 'São Paulo');
});

test('atualizarSemMutar devolve versão nova sem tocar no original', () => {
  const original = { nome: 'Ana', idade: 15 };
  const nova = atualizarSemMutar(original, 'idade', 16);
  assert.equal(original.idade, 15);
  assert.equal(nova.idade, 16);
});

test('atualizarSemMutar troca campo aninhado sem alcançar o original', () => {
  const original = { nome: 'Ana', endereco: { cidade: 'São Paulo' } };
  const nova = atualizarSemMutar(original, 'endereco', { cidade: 'Campinas' });
  assert.equal(original.endereco.cidade, 'São Paulo');
  assert.equal(nova.endereco.cidade, 'Campinas');
});

solutionCode:
export function copiarProfundo(objeto) {
  return structuredClone(objeto);
}

export function atualizarSemMutar(original, chave, valor) {
  const copia = structuredClone(original);
  copia[chave] = valor;
  return copia;
}
